<?php require 'db.php'; require 'helpers.php'; $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$mobile=trim($_POST['mobile']??'');$enroll=trim($_POST['enrollment_number']??'');$course=trim($_POST['course']??'');$password=$_POST['password']??'';if(mb_strlen($name)<2)$errors[]='Enter a valid name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!preg_match('/^[0-9+() -]{8,20}$/',$mobile))$errors[]='Enter a valid mobile number.';if($enroll==='')$errors[]='Enrollment number is required.';if($course==='')$errors[]='Select a course.';if(!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&]).{8,}$/',$password))$errors[]='Password needs 8+ chars, uppercase, lowercase, number and special character.';if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO users(name,email,username,password_hash,role) VALUES(?,?,?,?,?)');$s->execute([$name,$email,$email,password_hash($password,PASSWORD_DEFAULT),'student']);$uid=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO students(user_id,enrollment_number,name,email,mobile,course) VALUES(?,?,?,?,?,?)');$s->execute([$uid,$enroll,$name,$email,$mobile,$course]);$pdo->commit();flash('Registration successful. Please log in.');header('Location: login.php');exit;}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Email, username or enrollment number already exists.';}}} page_header('Student Registration');if($errors)echo '<div class="error">'.e(implode(' ',$errors)).'</div>'; ?>
<section class="panel"><h2>Create Student Account</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name</label><input name="name" required value="<?=e($_POST['name']??'')?>"><label>Email</label><input type="email" name="email" required value="<?=e($_POST['email']??'')?>"><label>Mobile</label><input name="mobile" required><label>Enrollment number</label><input name="enrollment_number" required><label>Course</label><select name="course" required><option value="">Choose course</option><?php foreach(['Computer Engineering','Information Technology','Computer Science','AI','Data Science'] as $c)echo '<option>'.e($c).'</option>';?></select><label>Password</label><input type="password" name="password" required minlength="8"><button>Create Account</button></form></section><?php page_footer(); ?>